(function(){'use strict';
const K=ArtifactCampaignDeck,A=ArtifactCampaign,D=ArtifactCampaignData,base=ARTIFACT_CARDS,all=Object.fromEntries([...base,...D.heroes].map(c=>[c.key,c])),root=document.querySelector('#campaign'),sound=new ArtifactAudio();
let p=A.fresh(),game=null,view='map',selection=null,focus=null,busy=false,message='',confirmKey=null,dialogue=0,noticeTimer;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try{const saved=JSON.parse(localStorage.getItem(A.SAVE_KEY));if(saved){K.migrate(saved);if(!A.valid(saved))throw Error('存档版本或队伍数据无效');p=K.migrate(saved);message=p.migrationNotice||'';if(p.battle){game=new A.CampaignGame(base);game.s=p.battle;view='map';}}}catch(e){message='未能读取剧情存档：'+e.message+'。原始数据未覆盖，请导出备份后再开始。';}
function save(){p.battle=game?game.s:null;try{localStorage.setItem(A.SAVE_KEY,JSON.stringify(p));}catch(e){notify('存档失败，请立即使用“导出存档”备份。');}}
function notify(t){document.querySelector('#notice').textContent=t;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>document.querySelector('#notice').textContent='',4500);}
const button=(action,label,extra='')=>`<button data-act="${action}" ${extra}>${label}</button>`;
const name=k=>all[k]?.name||k;
const art=k=>all[k]?.art||all.slark.art;
function top(){return `<header class="masthead"><a class="logo" href="index.html">A <span>ARTIFACT<small>暗月残片 · 独立剧情</small></span></a><nav>${button('map','旅程',view==='map'?'class="active"':'')}${button('party','同行者',view==='party'?'class="active"':'')}${button('deck','因果牌组',view==='deck'?'class="active"':'')}${button('journal','见闻',view==='journal'?'class="active"':'')}</nav><div class="tools">${button('audio',sound.enabled?'♫ 声音':'♪ 静音','aria-label="切换音乐音效"')}${button('export','导出存档')}<label class="import">导入<input type="file" id="import" accept="application/json"></label></div></header>`;}
function metrics(){return `<div class="metrics"><span>小鱼人 <b>Lv.${p.stage+1}</b></span><span>成长 <b>+${p.growth.attack} 攻 / +${p.growth.health} 血</b></span><span>共鸣 <b>${p.resonance}</b></span><span>污名 <b>${p.stigma.join(' / ')}</b><small>金钥匙 / 龙诗 / 羽毛</small></span><span>旅费 <b>${p.gold}</b></span>${p.forge?'<span>潮汐刃 <b>已锻造</b></span>':''}${p.scepter?`<span>神杖 <b>${p.scepterUsed?'已使用':'可用 · 旅程限一次'}</b></span>`:''}</div>`;}
function map(){if(p.cardReward)return cardReward();if(game?.s.winner!==null&&game)return result();if(p.stage>=D.stages.length)return ending();const st=D.stages[p.stage];return `<main class="atlas"><section class="prologue"><div><p class="eyebrow">DARK MOON FRAGMENTS / ${String(p.stage+1).padStart(2,'0')} OF 18</p><h1>暗月残片<span>鱼人的潮汐</span></h1><p class="motto">海从不问你来处。<br>但潮水，会带回你留下的一切。</p>${metrics()}<div class="hero-actions">${button(game?'resume':'story',game?'继续战斗':'启程 · '+st.title,'class="primary"')}${button('party','整理队伍 →')}</div><p class="fine">独立存档 · 1–3 条战线 · 每战最多 5 名英雄<br>小鱼人必须出战。阵亡英雄本关不复活，关后休整恢复。</p></div><div class="moon-art"><div class="moon"></div><img src="${art('slark')}" alt="小鱼人斯拉克"><span>“真正的自由，<br>是选择和谁一起归航。”</span></div></section><section class="route"><div class="section-title"><p class="eyebrow">THE LONG WAY HOME</p><h2>潮汐航路</h2><span>${p.completed.length} / 18 已完成</span></div><div class="nodes">${D.stages.map((s,i)=>`<button class="node ${i===p.stage?'current':''} ${i<p.stage?'done':''}" data-act="${i===p.stage?'story':'chapter'}" data-key="${i}" ${i>p.stage?'disabled':''}><span class="node-number">${i<p.stage?'✓':String(i+1).padStart(2,'0')}</span><span><small>${s.act}</small><strong>${s.title}</strong><em>${s.lanes} 路 · ${D.objectives[s.kind]}</em></span><span>${i===p.stage?'→':i>p.stage?'·':''}</span></button>`).join('')}</div></section></main>`;}
function party(){return `<main class="camp"><p class="eyebrow">THE ONES WHO STAY</p><h1>同行者 <small>${p.party.length} / 5</small></h1><p>击败并理解一个人，才可能与他同行。点击英雄安排出战；小鱼人始终在队伍中。</p>${metrics()}${game?'<p class="warning">当前战斗的队伍已锁定。完成或撤退后才能更换。</p>':''}<div class="roster">${p.roster.map(k=>`<article class="companion ${p.party.includes(k)?'chosen':''}"><img src="${art(k)}" alt="${esc(name(k))}"><div><small>${p.broken.includes(k)?'已决裂 · 终局将成为敌人':k==='slark'?'每战必选':'羁绊 '+('◆'.repeat(p.loyalty[k]||0))+('◇'.repeat(5-(p.loyalty[k]||0)))}</small><h2>${esc(name(k))}</h2><p>⚔ ${all[k].attack}　♥ ${all[k].health}　◇ ${all[k].armor||0}</p><div>${button('toggle',k==='slark'?'必定同行':p.party.includes(k)?'已出战 ✓':'加入队伍',`data-key="${k}" ${game||k==='slark'||p.broken.includes(k)?'disabled':''}`)}${k!=='slark'&&!p.broken.includes(k)?button('break','决裂',`class="text-danger" data-key="${k}" ${game?'disabled':''}`):''}</div>${p.party.includes(k)&&!game?`<label class="placement-label">初始战线 <select data-placement="${k}">${Array.from({length:D.stages[p.stage]?.lanes||1},(_,l)=>`<option value="${l}" ${(p.placements?.[k]??p.party.indexOf(k))%(D.stages[p.stage]?.lanes||1)===l?'selected':''}>第 ${l+1} 路</option>`).join('')}</select></label>`:''}</div></article>`).join('')}</div><section class="camp-shop"><h2>海岸营地</h2><p>装备会在每场战斗开始时自动给予小鱼人。同一武器槽不会叠加；关内临时增益在休整时消退。</p>${[['short_sword','短剑',40],['broadsword','阔剑',90],['claymore','大剑',160]].map(([k,n,c])=>button('buy',`${p.weapon===k?'已装备 · ':''}${n} / ${c} 旅费`,`data-key="${k}" data-price="${c}" ${game||p.gold<c||p.weapon===k?'disabled':''}`)).join(' ')}</section></main>`;}
function cardCopy(c){return K.describe(c,p);}
function cardReward(){return `<main class="camp reward-camp"><p class="eyebrow">CHOOSE YOUR NEXT POSSIBILITY</p><h1>选择一张卡牌</h1><p>三选一加入你的牌组，也可以跳过，保持关键牌的抽取概率。奖励已固定，刷新不会重抽。</p><div class="reward-cards">${p.cardReward.offers.map(k=>{const c=D.cards.find(c=>c.key===k);return `<article class="deck-card"><img src="${art(c.portrait)}" alt=""><span class="cost">${c.mana}</span><small class="rarity">${c.upgraded?'已升级 · ':''}${({Common:'普通',Uncommon:'非凡',Rare:'稀有'})[c.rarity]}</small><h3>${c.name}</h3><p>${cardCopy(c)}</p><footer>${button('claim-card','加入牌组',`data-key="${k}" class="primary" ${p.deck.length>=30?'disabled':''}`)}</footer></article>`;}).join('')}</div><div class="hero-actions">${button('claim-card','跳过 · 不加入卡牌','data-key="skip"')}${button('deck','查看当前牌组')}</div></main>`;}
function deck(){const keys=[...new Set(p.deck)];return `<main class="camp"><p class="eyebrow">BUILD WHAT YOU FIND</p><h1>因果牌组 <small>${p.deck.length} 张</small></h1><p>战斗胜利后三选一卡，可跳过。每轮抽 5 张，轮末弃置剩余手牌；弃牌堆洗回牌库。更厚的牌组有更多工具，也更难及时抽到核心牌。</p><p>营地每次可升级一张卡（50 旅费），或移除一张卡（35 旅费）；至少保留 8 张。升级只改变所选的一张副本，不会同时升级同名牌。</p>${p.cardReward?button('map','返回三选一奖励','class="primary"'):''}<div class="deck-grid">${keys.map(k=>{const c=D.cards.find(c=>c.key===k);return `<article class="deck-card"><img src="${art(c.portrait)}" alt=""><span class="cost">${c.mana}</span><h3>${c.name} ×${p.deck.filter(v=>v===k).length}</h3><p>${cardCopy(c)}</p><footer>${button('upgrade','升级一张 · 50',`data-key="${k}" ${game||c.upgraded||p.gold<50||p.campActions?.upgrade?'disabled':''}`)}${button('remove','移除一张 · 35',`data-key="${k}" ${game||p.gold<35||p.deck.length<=8||p.campActions?.remove?'disabled':''}`)}</footer></article>`;}).join('')}</div><details class="card-pool"><summary>可能遇见的卡牌 · 不可直接领取</summary><div class="deck-grid">${D.cards.filter(c=>!c.upgraded&&c.key!=='story_scepter').map(c=>`<article class="deck-card"><img src="${art(c.portrait)}" alt=""><h3>${c.name} · ${c.mana} 魔力</h3><p>${cardCopy(c)}</p></article>`).join('')}</div></details></main>`;}

function journal(){return `<main class="camp reading"><p class="eyebrow">WHAT THE SEA REMEMBERS</p><h1>潮汐见闻</h1><p>污名吸引对应追猎者，增加其生命。追求共鸣会更快成长，却会降低同行者羁绊；终幕失去共鸣攻击，并承受共鸣反噬。亲密队友获得额外攻击，约定牌效果更强。</p>${p.journal.length?p.journal.map(j=>`<article><small>第 ${j.stage+1} 章 · ${({bond:'守住约定',train:'磨炼技艺',power:'汲取暗月'})[j.choice]}</small><h2>${esc(j.title)}</h2><p>${esc(D.stages[j.stage].outro)}</p><blockquote>${esc(j.clue)}</blockquote></article>`).join(''):'<p>你还未离开暗礁。第一份记录，等待一次选择。</p>'}<details><summary>关于世界观与素材</summary><p>本模式为 Dota / Artifact 同人改编；暗礁起源、残月阴谋和剧情技能数值属于原创设定，不代表官方正史。</p><p>新增英雄图像来自 Valve Steam CDN，技能参考 OpenDota 的 Dota 2 数据。原作角色与素材归 Valve 所有。</p><a href="assets/campaign/sources.json" target="_blank" rel="noopener">查看素材来源</a> · <a href="assets/campaign/ability-references.json" target="_blank" rel="noopener">查看技能参考</a></details></main>`;}
function story(){const st=D.stages[p.stage],line=st.intro[dialogue];return `<main class="story reading"><p class="eyebrow">${st.act} / ${st.place}</p><h1>${st.title}</h1><div class="dialogue"><small>${esc(line[0])}</small><p>“${esc(line[1])}”</p><div class="dialogue-progress">${st.intro.map((_,i)=>`<i class="${i<=dialogue?'lit':''}"></i>`).join('')}</div></div><section class="brief"><h3>此次旅程</h3><p>${st.lanes} 条战线 · ${D.objectives[st.kind]}</p><p>限时 ${st.rounds} 轮 · 敌方主将 ${st.hp} 生命 / ${st.atk} 攻击。全体出战英雄阵亡即失败。</p>${st.rule?`<p class="warning">${({stone:'小小第一轮完全免疫伤害。先保护队伍，等待山心暴露。',web:'蜘蛛每两轮召来新的幼蛛。',mirror:'攻击法术会被折镜反射 2 点穿甲伤害。'})[st.rule]}</p>`:''}${st.pursuit?'<p class="warning">追猎者每轮使用跳刀跨线，落点会提前预告。缴械／眩晕可以打断，也可用闪烁匕首转移被追杀的英雄。</p>':''}${st.drain?'<p class="warning">暗月抽离：共鸣攻击归零，成长攻击保留 35%；小鱼人受到共鸣 ÷ 3 的初始反噬。</p>':''}</section><div class="hero-actions">${button(dialogue<st.intro.length-1?'next':'begin',dialogue<st.intro.length-1?'继续对话 →':'确认队伍，进入战斗','class="primary"')}${button('party','调整队伍')}</div></main>`;}
function result(){const st=game.stage(),won=game.s.winner===0;return `<div class="veil"><section class="result"><p class="eyebrow">${won?'THE TIDE REMEMBERS':'THE SEA OFFERS ANOTHER CHANCE'}</p><h1>${won?'潮汐向前':'暂别此岸'}</h1><p>${won?st.outro:game.s.log.at(-1)?.text}</p>${won?`<blockquote>${st.clue}</blockquote><p>成长生命 +1，旅费 +35${st.recruit?'；'+name(st.recruit)+(st.bonusRecruit?'、'+name(st.bonusRecruit):'')+' 可加入队伍':''}。选择一项永久改变：</p><div class="choices">${button('reward','<b>守住约定</b><span>同行羁绊 +1<br>格挡牌治疗 +1（上限 4）</span>','data-key="bond"')}${button('reward','<b>磨炼技艺</b><span>成长攻击 +0.5<br>能量转移伤害 +1（上限 4）</span>','data-key="train"')}${button('reward','<b>汲取暗月</b><span>成长攻击 +1 / 额外共鸣 +2<br>污名 +1，同行羁绊 −1</span>','data-key="power"')}</div>`:`<p>关前成长保留，可调整队伍、牌组后重试。神杖一旦使用，不会因失败返还。</p>${button('retry','回到营地','class="primary"')}`}</section></div>`;}
function ending(){const loyal=p.roster.filter(k=>k!=='slark'&&!p.broken.includes(k)&&p.loyalty[k]>=3).length;return `<main class="story reading"><p class="eyebrow">EPILOGUE / ${loyal>=3?'归航':p.broken.length?'残岸':'微光'}</p><h1>${loyal>=3?'海的另一边':p.broken.length?'潮水记得所有名字':'一盏仍亮的灯'}</h1><p class="ending-copy">${loyal>=3?'山心回到山上，蛛丝补好了村子的帆。斯拉达不再守门，拉比克学会了先问再借。小鱼人没有成为新的锁；他和同行者轮流守望潮汐，第一次拥有了可以离开的家。':p.broken.length?'裂缝合拢了。有些名字却永远留在了桥上。小鱼人把潮汐刃放回海中，用余生寻找那些无法被力量偿还的答案。':'暗月退去，海岸还有一盏灯。小鱼人坐在灯下，给曾经同行的人写信。自由来得很慢，但这一次，他愿意等。'}</p>${metrics()}<p>${loyal} 位深厚羁绊 · ${p.broken.length} 位决裂同伴 · ${p.resonance} 暗月共鸣</p>${button('journal','重读旅程','class="primary"')}${button('restart','开启新的旅程')}</main>`;}
function render(){root.innerHTML=top()+(message?`<p class="warning">${esc(message)}</p>`:'')+({map,party,deck,journal,story}[view]||map)()+(confirmKey?`<div class="veil"><section class="result"><h2>${confirmKey==='restart'?'开启新的旅程？':confirmKey==='retreat'?'撤退到营地？':'与 '+esc(name(confirmKey))+' 决裂？'}</h2><p>${confirmKey==='restart'?'将覆盖当前剧情存档，经典对战不受影响。建议先导出备份。':confirmKey==='retreat'?'本关进度会重置，永久成长保留。':'获得 50 旅费与 1 攻击、2 共鸣，但这位同伴将永久离队，并在终局以强化幻影回归。'}</p>${button('confirm','确认','class="primary"')}${button('cancel','返回')}</section></div>`:'');}
root.addEventListener('click',async e=>{const b=e.target.closest('[data-act]');if(!b||b.disabled||busy)return;try{await sound.start();if(busy)return;const act=b.dataset.act,k=b.dataset.key;if(['map','party','deck','journal'].includes(act)){view=act;selection=null;}else switch(act){
 case 'audio':sound.enabled=!sound.enabled;sound.setVolumes();break;
 case 'story':if(game){location.href='campaign-battle.html';return;}dialogue=0;view='story';break;
 case 'next':dialogue++;break;
 case 'begin':game=new A.CampaignGame(base);game.begin(p);save();location.href='campaign-battle.html';return;
 case 'resume':location.href='campaign-battle.html';return;
 case 'toggle':A.chooseParty(p,k);save();break;
 case 'break':confirmKey=k;break;
 case 'restart':confirmKey='restart';break;
 case 'retreat':confirmKey='retreat';break;
 case 'cancel':confirmKey=null;break;
 case 'confirm':if(confirmKey==='restart'){p=A.fresh();game=null;view='map';}else if(confirmKey==='retreat'){game=null;view='party';sound.setScene('menu');}else A.abandon(p,confirmKey);confirmKey=null;save();break;
 case 'buy':if(game)throw Error('战斗中无法购买');{const price={short_sword:40,broadsword:90,claymore:160}[k];if(!price||p.gold<price)throw Error('旅费不足');p.gold-=price;p.weapon=k;save();sound.play('buy');}break;
 case 'claim-card':K.claim(p,k);save();view='map';break;
 case 'upgrade':K.upgrade(p,k);save();break;
 case 'remove':K.remove(p,k);save();break;
 case 'reward':A.reward(p,game,k);game=null;view='map';sound.setScene('menu');save();break;
 case 'retry':game=null;view='party';sound.setScene('menu');save();break;
 case 'export':{const url=URL.createObjectURL(new Blob([JSON.stringify(p,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='dark-moon-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 case 'chapter':notify(D.stages[Number(k)].clue);return;
 }render();}catch(err){busy=false;notify(err.message);}});
root.addEventListener('change',async e=>{if(e.target.dataset.placement){p.placements||={};p.placements[e.target.dataset.placement]=Number(e.target.value);save();return;}if(e.target.id!=='import')return;try{const raw=JSON.parse(await e.target.files[0].text());if(!A.valid(raw))throw Error('不是有效的暗月剧情存档');if(!window.confirm('导入将替换当前剧情进度，是否继续？'))return;p=raw;game=null;if(p.battle){game=new A.CampaignGame(base);game.s=p.battle;}view='map';message='';save();render();}catch(err){notify('导入失败：'+err.message);}});
document.addEventListener('visibilitychange',()=>sound.visibility(document.hidden));
render();
})();
